	private static boolean emitCsg(PackedJoinHypergraph graph, Receiver receiver,
			ConnectingEdgeLookup connectingEdges, long subgraph) {
		long forbidden = subgraph | nodesBelowInclusive(Long.numberOfTrailingZeros(subgraph));
		long neighborhood = connectingEdges.neighborhood(subgraph, forbidden);
		for (long rest = neighborhood; rest != 0L;) {
			int node = Long.SIZE - 1 - Long.numberOfLeadingZeros(rest);
			rest &= ~bit(node);
			long complement = bit(node);
			int edge = connectingEdges.find(subgraph, complement);
			if (edge >= 0 && receiver.foundSubgraphPair(subgraph, complement, edge)) {
				return true;
			}
			long complementForbidden = forbidden | (neighborhood & nodesBelowInclusive(node));
			if (enumerateCmpRec(graph, receiver, connectingEdges, subgraph, complement,
					complementForbidden)) {
				return true;
			}
		}
		return false;
	}

