	private static long bit(int node) {
		return 1L << node;
	}

	private static long lowestBit(long nodes) {
		return nodes & -nodes;
	}

	private static long nodesBelowInclusive(int node) {
		return node == Long.SIZE - 1 ? -1L : (1L << node + 1) - 1L;
	}

	private static long nextSubset(long subset, long superset) {
		return (subset - superset) & superset;
	}

	private static boolean isSubset(long subset, long superset) {
		return (subset & ~superset) == 0L;
	}

	private static final class OneWordReceiverAdapter implements Receiver {

		private final PackedNodeSetArena nodeSets;
		private final PackedDphypReceiver receiver;

		private OneWordReceiverAdapter(PackedNodeSetArena nodeSets, PackedDphypReceiver receiver) {
			this.nodeSets = nodeSets;
			this.receiver = receiver;
		}

		@Override
		public boolean hasSeen(long nodes) {
			int nodeSetId = nodeSets.intern(nodes);
			return nodeSetId != 0 && receiver.hasSeen(nodeSetId);
		}

		@Override
		public boolean foundSingleNode(int node) {
			return nodeSets.singleton(node) == 0 || receiver.foundSingleNode(node);
		}

		@Override
		public boolean foundSubgraphPair(long left, long right, int edge) {
			int leftNodeSetId = nodeSets.intern(left);
			int rightNodeSetId = nodeSets.intern(right);
			return leftNodeSetId == 0 || rightNodeSetId == 0
					|| receiver.foundSubgraphPair(leftNodeSetId, rightNodeSetId, edge);
		}
	}

	private static final class WideConnectingEdgeLookup {

		private final PackedJoinHypergraph graph;
		private final PackedNodeSetArena nodeSets;
		private final ConnectingEdgeIndex connectingEdges;
		private final int[] edgeIncidenceCounts;
		private final int[] neighborhoodArcs;

		private WideConnectingEdgeLookup(PackedJoinHypergraph graph, PackedNodeSetArena nodeSets) {
			this.graph = graph;
			this.nodeSets = nodeSets;
			connectingEdges = ConnectingEdgeIndex.wide(graph, nodeSets);
			edgeIncidenceCounts = new int[graph.nodeCount()];
			neighborhoodArcs = wideNeighborhoodArcs(graph, nodeSets, edgeIncidenceCounts);
		}

		private int find(int leftNodes, int rightNodes) {
			int lowest = findSingletonEdge(leftNodes, rightNodes, Integer.MAX_VALUE);
			if (lowest == 0) {
				return 0;
			}
			lowest = findSingletonEdge(rightNodes, leftNodes, lowest);
			if (lowest == 0) {
				return 0;
			}
			for (int edge : connectingEdges.compoundEdges()) {
				if (edge >= lowest) {
					break;
				}
				int edgeLeft = graph.edgeLeftNodeSet(edge);
				int edgeRight = graph.edgeRightNodeSet(edge);
				if (nodeSets.isSubset(edgeLeft, leftNodes) && nodeSets.isSubset(edgeRight, rightNodes)
						|| nodeSets.isSubset(edgeLeft, rightNodes) && nodeSets.isSubset(edgeRight, leftNodes)) {
					return edge;
				}
			}
			return lowest == Integer.MAX_VALUE ? -1 : lowest;
		}

		private int findSingletonEdge(int singletonSide, int oppositeSide, int lowest) {
			int[] starts = connectingEdges.singletonEdgeStarts();
			int[] edges = connectingEdges.singletonEdges();
			for (int node = nodeSets.nextMember(singletonSide, 0); node >= 0; node = nodeSets.nextMember(singletonSide,
					node + 1)) {
				for (int index = starts[node]; index < starts[node + 1]; index++) {
					int edge = edges[index];
					if (edge >= lowest) {
						break;
					}
					int left = graph.edgeLeftNodeSet(edge);
					int required = nodeSets.cardinality(left) == 1 && nodeSets.contains(left, node)
							? graph.edgeRightNodeSet(edge)
							: left;
					if (nodeSets.isSubset(required, oppositeSide)) {
						lowest = edge;
						break;
					}
				}
			}
			return lowest;
		}

		private int neighborhood(int subgraph, int forbidden) {
			int blocked = nodeSets.union(subgraph, forbidden);
			if (blocked == 0 && subgraph != 0) {
				return 0;
			}
			long rawWork = 0L;
			for (int node = nodeSets.nextMember(subgraph, 0); node >= 0; node = nodeSets.nextMember(subgraph,
					node + 1)) {
				rawWork += (long) edgeIncidenceCounts[node] << 1;
			}
			if (rawWork <= neighborhoodArcs.length) {
				return neighborhoodFromIncidences(subgraph, blocked);
			}
			int result = 0;
			for (int arc : neighborhoodArcs) {
				int edge = arc >>> 1;
				int near = (arc & 1) == 0 ? graph.edgeLeftNodeSet(edge) : graph.edgeRightNodeSet(edge);
				int far = (arc & 1) == 0 ? graph.edgeRightNodeSet(edge) : graph.edgeLeftNodeSet(edge);
				result = addWideNeighbor(subgraph, blocked, result, near, far);
				if (nodeSets.resourceLimitReached()) {
					return 0;
				}
			}
			return result;
		}

		private int neighborhoodFromIncidences(int subgraph, int blocked) {
			int result = 0;
			for (int node = nodeSets.nextMember(subgraph, 0); node >= 0; node = nodeSets.nextMember(subgraph,
					node + 1)) {
				for (int incidence = graph.firstEdgeIncidence(node); incidence >= 0; incidence = graph
						.nextEdgeIncidence(incidence)) {
					int edge = graph.edgeIncidenceEdge(incidence);
					result = addWideNeighbor(subgraph, blocked, result,
							graph.edgeLeftNodeSet(edge), graph.edgeRightNodeSet(edge));
					if (nodeSets.resourceLimitReached()) {
						return 0;
					}
					result = addWideNeighbor(subgraph, blocked, result,
							graph.edgeRightNodeSet(edge), graph.edgeLeftNodeSet(edge));
					if (nodeSets.resourceLimitReached()) {
						return 0;
					}
				}
			}
			return result;
		}

		private int addWideNeighbor(int subgraph, int blocked, int result, int near, int far) {
			if (!nodeSets.isSubset(near, subgraph) || nodeSets.intersects(far, blocked)
					|| nodeSets.intersects(far, result)) {
				return result;
			}
			return nodeSets.union(result, nodeSets.lowestMemberSet(far));
		}
	}

